export function subscribe(name: string, uniqueid: string, cb: (status: Object, err: string) => any) {

    console.log('PubSub subscribe', name, uniqueid)

    let found = namesMap.get(name)
    if (found === undefined) {

        let found: localMapItem = {
            // status: {} as Object,
            map: new Map<string, () => any>(),
        }
        found.map.set(uniqueid, cb)
        namesMap.set(name, found)

    } else {
        if (found !== undefined) {
            // replace the callback
            found.map.set(uniqueid, cb)
            // just go again
        }
    }
}

export function publish(name: string, status: Object) {

    const found = namesMap.get(name)
    if (found !== undefined) {
        let keys = found.map.keys()
        let keyArray = Array.from(keys)
        for (let key of keyArray) {
            let cb = found.map.get(key)
            if (cb !== undefined) {
                console.log('pubsub publish', name, key, status)
                cb(status, "")
            } else {
                console.log('pubsub publish callback is undefined', name, key)
            }
        }
    } else {
        // console.log('PubSub didnt find name', name)
    }

}


